#!/usr/bin/env node
/* P15 original DOS Tomb/Portal witnessed RGB-floor preview and export parity.
 * Refs are independently generated by Python from pinned O115 original witness
 * report files + canonical MK2 GRA, NOT TypeScript decoder output.
 */
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),crypto=require('node:crypto');
let ts;try{ts=require('typescript')}catch{ts=require('/opt/nvm/versions/node/v22.16.0/lib/node_modules/typescript')}
for(const ext of ['.ts','.tsx'])require.extensions[ext]=(m,file)=>m._compile(ts.transpileModule(fs.readFileSync(file,'utf8'),{fileName:file,compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022,esModuleInterop:true}}).outputText,file);
if(!globalThis.crypto)globalThis.crypto=crypto.webcrypto;
const {buildMK2ObservedFloorsP15}=require('../src/core/assets/mk2ObservedFloorColorsP15.ts');
const {selectedZip}=require('../src/core/assets/export.ts');
const {parseAnimationStoreZip,decodeAnimationBundlePng}=require('../src/games/mk1/research/browserAnimationExportBundleValidation.ts');
const reference=require('./fixtures/mk2-p15-floor-original-witness-parity.json');
const root=process.argv[2];if(!root)throw Error('Usage: verify-mk2-p15-observed-floors.cjs <canonical MK2 dir> [report.json]');
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');let checks=0;
function eq(a,b,why){assert.deepStrictEqual(a,b,why);checks++}
const input=new Map();for(const f of ['mk2.exe','tomb.gra','portal.gra'])input.set(f,new Uint8Array(fs.readFileSync(path.join(root,f))));
function dir(map,isSynthetic=false){return {directoryName:'P15 original local MK2',isSynthetic,
 async listRecursive(){return [...map].map(([p,b])=>({path:p,name:path.basename(p),extension:path.extname(p).slice(1).toUpperCase(),size:b.length}));},
 async readSlice(p,start,size){const b=map.get(p);if(!b)throw Error('Missing source '+p);return b.slice(start,start+size);}}}
(async()=>{
 eq(reference.schema,'mk2_p15_original_floor_screenshot_witness_reference_v1','independent original screenshot reference');
 eq(sha(input.get('mk2.exe')),'fa93afdc74160ef7bccf1454cd951bdf6008fb418d9c97f9e8c44a36f29f2c65','canonical original EXE');
 const result=await buildMK2ObservedFloorsP15(dir(input));
 eq(result.status.status,'VERIFIED','both original screenshot-matched floor source layers');
 eq(result.assets.length,2,'two new original-indexed assets');eq(result.status.count,2,'status count');
 eq(new Set(result.assets.map(x=>x.id)).size,2,'distinct IDs');
 eq(result.packages.length,1,'one provenance archive');
 const zip=parseAnimationStoreZip(result.packages[0].bytes),man=JSON.parse(new TextDecoder().decode(zip.get('manifest.json').bytes));
 eq(man.records.length,2,'two source records');eq(man.nativePaletteBankKnown,false,'unknown original native DAC bank');
 eq(man.completeStage,false,'not a complete stage');eq(man.liveCameraKnown,false,'no live camera');
 eq([...zip.keys()].filter(x=>x.startsWith('indexed/')).length,6,'six original/uncertainty binary payloads');
 eq([...zip.keys()].filter(x=>x.startsWith('preview/')).length,2,'two real preview PNGs');
 for(const ref of reference.stages){
  const a=result.assets.find(x=>x.id===`mk2-witnessed-floor:${ref.stage}:x${ref.left}`);
  eq(Boolean(a),true,`source asset ${ref.stage}`);eq(sha(input.get(ref.resource)),ref.resourceSHA256,`full source checksum ${ref.stage}`);
  eq(a.kind,'stage',`floor kind ${ref.stage}`);eq(a.width,320,`floor width ${ref.stage}`);eq(a.height,ref.rows,`source rows ${ref.stage}`);
  eq(a.source.offset,ref.sourceOffset,`source original offset ${ref.stage}`);eq(a.source.length,896*ref.rows,`full packed floor suffix ${ref.stage}`);
  eq(a.metadata.sourceLeft,ref.left,`screenshot-conditional source x ${ref.stage}`);
  eq(a.metadata.originalScreenshotHeldOutExactMatches,ref.heldoutExactPixels,`held out witness count ${ref.stage}`);
  eq(a.metadata.nativePaletteKnown,false,`native palette unresolved ${ref.stage}`);
  eq(a.metadata.runtimeNativeDACBankKnown,false,`original allocator unresolved ${ref.stage}`);
  eq(a.metadata.runtimeCameraKnown,false,`live camera unresolved ${ref.stage}`);
  eq(a.metadata.fullStageScene,false,`full scene unresolved ${ref.stage}`);
  eq(a.metadata.indices.length,ref.pixelCount,`source index-plane length ${ref.stage}`);
  eq(sha(a.metadata.indices),ref.indicesSHA256,`independent original source-index parity ${ref.stage}`);
  eq(sha(a.rgba),ref.rgbaSHA256,`independently screenshot-witnessed O115 RGBA ${ref.stage}`);
  eq(a.metadata.mask.every(v=>v===1),true,`original source pixels paint covered ${ref.stage}`);
  eq(a.metadata.paletteKnownMask.every(v=>v===0),true,`native palette ownership unknown despite witnessed RGB ${ref.stage}`);
  const seen=new Set(a.metadata.indices);eq(seen.size,ref.observedIndexCount,`exact native distinct indices ${ref.stage}`);
  eq(Math.min(...seen)>=ref.lo&&Math.max(...seen)<=ref.hi,true,`O115 observed raw-index domain ${ref.stage}`);
  const idx=zip.get(`indexed/${ref.stage}.indices.bin`).bytes;
  const mask=zip.get(`indexed/${ref.stage}.mask.bin`).bytes;
  const paletteKnownMask=zip.get(`indexed/${ref.stage}.native-palette-known.bin`).bytes;
  eq(sha(idx),ref.indicesSHA256,`forensic ZIP exact original indices ${ref.stage}`);
  eq(sha(mask),ref.sourcePaintMaskSHA256,`forensic ZIP full coverage mask ${ref.stage}`);
  eq(sha(paletteKnownMask),ref.paletteKnownMaskSHA256,`forensic ZIP native palette uncertainty mask ${ref.stage}`);
  const png=zip.get(`preview/${ref.stage}_observed_floor_320x${ref.rows}.png`).bytes;
  const decoded=decodeAnimationBundlePng(png);
  eq(decoded.width,320,`PNG dimensions width ${ref.stage}`);eq(decoded.height,ref.rows,`PNG dimensions rows ${ref.stage}`);
  eq(sha(decoded.rgba),ref.rgbaSHA256,`independently redecoded ZIP PNG pixels ${ref.stage}`);
  // No byte from the source index-plane is changed by its screenshot colour preview.
  const original=input.get(ref.resource),begin=ref.sourceOffset;
  for(let y=0;y<ref.rows;y++)for(let x=0;x<320;x++){
    eq(a.metadata.indices[y*320+x],original[begin+y*896+ref.left+x],`source-byte ${ref.stage}:${y}:${x}`);
  }
 }
 const selected=parseAnimationStoreZip(selectedZip(result.assets));
 eq([...selected.keys()].filter(n=>n.startsWith('assets/')).length,2,'both screenshot-colour PNGs selected/exported');
 eq([...selected.keys()].filter(n=>n.startsWith('indexed/')).length,6,'index, mask and native-palette-unknown for both');
 const order=JSON.parse(new TextDecoder().decode(selected.get('manifest.json').bytes));
 eq(order.selectionOrder.map(r=>r.id),result.assets.map(a=>a.id),'source-order retained');
 for(let i=0;i<result.assets.length;i++)for(const field of ['indices','mask','paletteKnownMask']){
  eq(sha(selected.get(`indexed/${String(i).padStart(5,'0')}_${field}.bin`).bytes),sha(result.assets[i].metadata[field]),`selected exact ${i}:${field}`);
 }
 let negatives=0;
 for(const name of ['mk2.exe','tomb.gra','portal.gra']){
  const bad=new Map(input),altered=bad.get(name).slice();altered[0]^=1;bad.set(name,altered);
  const fail=await buildMK2ObservedFloorsP15(dir(bad));
  eq(fail.assets.length,name==='mk2.exe'?0:1,'tampered '+name+' fail closed');negatives++;
  const missing=new Map(input);missing.delete(name);
  const gone=await buildMK2ObservedFloorsP15(dir(missing));
  eq(gone.assets.length,name==='mk2.exe'?0:1,'missing '+name+' fail closed');negatives++;
  const duplicate=new Map(input);duplicate.set(name.toUpperCase(),input.get(name));
  const ambiguous=await buildMK2ObservedFloorsP15(dir(duplicate));
  eq(ambiguous.assets.length,name==='mk2.exe'?0:1,'ambiguous '+name+' fail closed');negatives++;
 }
 const synthetic=await buildMK2ObservedFloorsP15(dir(input,true));eq(synthetic.assets.length,0,'synthetic source never qualifies');negatives++;
 const o={pass:'P15',status:'PASS',checks,independentOriginalWitness:'O115 screenshot RGB tables, O117 Tomb control and O115B Portal control',
  assets:2,sourcePixels:reference.stages.reduce((n,x)=>n+x.pixelCount,0),
  nativePaletteKnown:false,liveCameraKnown:false,completeStage:false,
  sourceArchiveSha256:sha(result.packages[0].bytes),negativeFixtureVariants:negatives};
 if(process.argv[3])fs.writeFileSync(process.argv[3],JSON.stringify(o,null,2)+'\n');
 if(process.argv[4])fs.writeFileSync(process.argv[4],result.packages[0].bytes);
 console.log(JSON.stringify(o,null,2));
})().catch(e=>{console.error(e.stack||e);process.exitCode=1});
